fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    var sum = 0;
    var n = 1;
    while n <= 40 {
        sum = sum + n;
        n = n + 1;
    }

    var product = 1;
    var factor = 1;
    while factor <= 8 {
        product = product * factor;
        factor = factor + 1;
    }

    io.write(text: sum.to_text().concat(other: " ").concat(other: product.to_text()))?;
    return Ok(unit);
}

fn sum_to(n: Int) -> Int {
    var total = 0;
    var current = 1;
    while current <= n {
        total = total + current;
        current = current + 1;
    }
    total
}

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    io.write(text: "12: ".concat(other: sum_to(n: 12).to_text()).concat(other: "\n"))?;
    io.write(text: "30: ".concat(other: sum_to(n: 30).to_text()).concat(other: "\n"))?;
    io.write(text: "7: ".concat(other: sum_to(n: 7).to_text()).concat(other: "\n"))?;
    return Ok(unit);
}
